    excerpt: { ar: "بعض الناس يستعجلون عذاب الله بأيديهم: ينحرف المستقر، ويدخّن أو يشرب من يكفيه رزقه، ويتفلّت من أولاده الصلاح. فنزن أعمالنا بميزان القرآن، ولا نستعجل العذاب بل نتعجّل رحمة الله.", en: "Some people hasten Allah's punishment with their own hands: the steady one goes astray, one whose provision suffices him smokes or drinks, and righteousness slips away from his children. So let us weigh our deeds by the balance of the Qur'an, and not hasten the punishment but hasten toward Allah's mercy." },
