    excerpt: { ar: "وقفة مع أول آية الكرسي: الله الحيّ الذي لا يغلبه الدهر، القيّوم القائم على كل شأن في بيتك وطريقك، الذي لا تأخذه سِنة ولا نوم، وله ما في السماوات والأرض، فلا يعجزه حفظ ما بين يديك.", en: "A pause at the beginning of Ayat al-Kursi: Allah, the Ever-Living, whom time does not overcome, the Self-Sustaining who stands over every affair in your home and on your way, whom neither drowsiness nor sleep overtakes, to whom belongs all that is in the heavens and the earth, so that guarding what is in your hands is no burden to Him." },
