    excerpt: { ar: "حديث ابن عباس «احفظ الله يحفظك»: حفظ الله في الشرع والنعم، والحفظ في الدين والدنيا، واستشعار معيته، والفرق بين السؤال والاستعانة.\nوعلاج الخوف من الناس بأن ما كُتب قد جفّ، ومساءلة الأب نفسه: من أنا في أعين عيالي؟", en: "Ibn Abbas's hadith \"Guard Allah and He will guard you\": guarding Allah in the Law and in His blessings, guarding in religion and in worldly life, being mindful of His companionship, and the difference between asking and seeking help. Fear of people is treated by remembering that what is written has dried, and the father is made to question himself: who am I in the eyes of my family?" },
