    excerpt: { ar: "من اقتران «كلوا مما رزقكم الله حلالًا طيبًا» بـ«واشكروا نعمة الله»: من التمس الحلال استشعر تمكين الله له، وعكس ذلك كِبرُ فرعون وغرور قارون.\nوالكفر بالنعمة يورث الطمع ثم التماس الوسائل والوقوع في المتشابهات.", en: "From the pairing of \"Eat of what Allah has provided you, lawful and good\" with \"and be grateful for the favor of Allah\": whoever seeks the lawful senses Allah's enabling of him, while the opposite is the arrogance of Pharaoh and the conceit of Qarun. Ingratitude for blessings breeds greed, then seeking means and falling into doubtful matters." },
