    excerpt: { ar: "وقفة مع قوله تعالى ﴿وَلَقَدْ آتَيْنَا دَاوُودَ مِنَّا فَضْلًا﴾: فضل الأوّاب الذاكر العامل، وامتداده في سليمان المسخَّرِ له الكون في سبيل الله.\nومن ذلك أن من وضع لعطائه لله حدًّا فليتوقع حدًّا في عطاء الله له، وأن الملك كله ينتهي بدابة الأرض وعصًا تسقط.", en: "A pause at the words of Allah \"And We certainly gave David bounty from Us\": the virtue of the oft-returning one who remembers and works, extended in Sulayman, for whom the universe was subjected in the cause of Allah. Hence, whoever sets a limit to his giving for Allah should expect a limit to Allah's giving to him, and all dominion ends with a creature of the earth and a staff that falls." },
