    excerpt: { ar: "آخر نداء إيماني في آل عمران ﴿اصبروا وصابروا ورابطوا﴾ ومكانه من هندسة النداءات: ستة نداءات لأهل الكتاب وسبعة للمؤمنين.\nسورة البقرة للبناء وآل عمران للثبات، والقرآن يرسم مناهج فكرية للأمة لا تفاصيل عبادات.", en: "The last call of faith in Al Imran, \"Be patient, persevere in patience, and remain stationed,\" and its place in the architecture of the calls: six to the People of the Book and seven to the believers. Al-Baqara is for building and Al Imran for steadfastness, and the Qur'an draws intellectual methodologies for the Ummah, not details of rituals." },
