    excerpt: { ar: "خاتمة سورة الغاشية ﴿فذكّر إنما أنت مذكّر﴾: وظيفتك التذكير والحساب والهداية بيد الله، فلا نحكم على أبنائنا ولا على الناس بحدود أعيننا.\nمثال عمر بن الخطاب قبل إسلامه، ودعوة لمن نستقلّه بأن يكثّر الله خيره.", en: "The conclusion of Surat al-Ghashiya, \"So remind, for you are only a reminder\": your function is reminding, while reckoning and guidance are in Allah's hands, so let us not judge our children or other people by the limits of our sight. The example of Umar ibn al-Khattab before his Islam, and a call for one we belittle: may Allah increase his good." },
