    excerpt: { ar: "سورة النصر ليست بشارةً تُريح بل تكليفٌ بمزيد من العمل: معنى التسبيح بكل ما خلق الله فينا، والاستغفار من التقصير دون الأكمل، وارتباطها بما قبلها وبعدها في النظم.\nوالتذكير بالقدوة لا بالقول وحده، والحياء من لقاء الله.", en: "Surat al-Nasr is not a reassuring glad tiding but a charge for more work: the meaning of glorifying Allah with everything He created in us, and seeking forgiveness for falling short of the best, and its link to what precedes and follows it in the composition. Also, reminding by example and not by word alone, and shame before meeting Allah." },
