    excerpt: { ar: "من قول بني إسرائيل لموسى بعد معجزة عبور البحر: «اجعل لنا إلهًا»، يستخلص الخاطرة أن لا أحد فوق الخطأ ولا يستحيل أن يُسلب منه الإيمان.\nفيدعو إلى متابعة القلب كما يتابع الأطباء شاشات الإنقاذ، وسؤال الله تمام الحياة مع الإيمان.", en: "From the words of the Children of Israel to Moses after the miracle of crossing the sea, \"Make for us a god,\" the khatira concludes that no one is above error and that it is not impossible for faith to be taken from anyone.\nIt calls us to monitor the heart as doctors watch life-support monitors, and to ask Allah for a life that ends with faith intact." },
