    excerpt: { ar: "ختام النداءات الإيمانية في سورة البقرة بآية الدَّين: ربط الآية بسابقاتها، ثم أن تحريم الربا استلزم فتح باب الدَّين، وأبواب المال الثلاثة عند الغني (الزكاة والصدقة والدَّين)، والأجل والكتابة والنظرة إلى ميسرة، وختامها بـ«ويعلّمكم الله».", en: "The close of the calls to the believers in Surat al-Baqara with the verse of debt: linking the verse to those before it; then that the prohibition of usury made opening the door of debt necessary; the three doors of money for the wealthy (zakat, charity, and debt); the term, the writing, and granting respite to one in hardship; and its ending with \"and Allah teaches you.\"" },
