    title: { ar: "تزكية النفس ودورك في صناعتها وماذا بعد رمضان", en: "Purifying the Soul, Your Role in Shaping It, and What Comes after Ramadan" },
    subtitle: { ar: "تزكية النفس: من أين أتيت؟ وما دورك في صناعة نفسك؟ وماذا بعد رمضان", en: "Purifying the soul: where did you come from, what is your role in shaping yourself, and what comes after Ramadan" },
    excerpt: { ar: "في سورتي الشمس والليل: محور تزكية النفس. للإنسان أصول وتشكيل ومستخرجات، وللقرآن إلغاء حجة «وجدنا آباءنا»، والعبادة جاءت تتعامل معي أنا. والفلاح غير النجاح، وما بعد رمضان امتدادٌ لا ختام.", en: "In Surat al-Shams and Surat al-Layl: the axis of purifying the self. The human being has origins, formation, and outcomes; the Qur'an abolishes the argument \"we found our fathers\"; and worship came to deal with me, myself. Success (falah) is not the same as achievement, and what follows Ramadan is a continuation, not a conclusion." },
