    excerpt: { ar: "وقفات مع قصة مؤمن آل فرعون في سورة غافر: كيف خاطبهم بمنطق الحقوق التي يعلنونها، وكيف ردّ فرعون بالتهديد المبطن، ولماذا ينسب الداعية قومه إلى نفسه وإن أساؤوا.\nويربط المتحدث ذلك بواقع المسلمين في الغرب وحملات التضخيم والكيل بمكيالين.", en: "Pauses with the story of the believer of Pharaoh's household in Surat Ghafir: how he addressed them with the logic of the rights they themselves proclaim, how Pharaoh responded with a veiled threat, and why the caller to Allah attributes his people to himself even when they wrong him.\nThe speaker ties this to the reality of Muslims in the West, amplification campaigns, and double standards." },
