    excerpt: { ar: "شرح باب التوبة من رياض الصالحين وسبب تقديمه بعد الإخلاص. التوبة ثلاث مراحل، وخطابها القرآني خطاب للمجتمع كله، واستغفار النبي ﷺ تعليم بأن لا أحد فوق احتمال الخطأ.", en: "An explanation of the chapter on repentance in Riyad al-Salihin and why it follows sincerity. Repentance has three stages, its Qur'anic address is addressed to the whole society, and the Prophet's (peace and blessings be upon him) seeking of forgiveness teaches that no one is above the possibility of error." },
