    excerpt: { ar: "وقفة عند «تخاصم أهل النار» ومثال زوجين يتلاومان بعد إدمان ابنهما، يقابله «تصالح أهل الجنة» ونزع الغل، وتشبيه النفس بالجوهرة يعلوها الغبار.", en: "A pause at \"the quarrel of the people of the Fire\" and the example of a couple blaming each other after their son's addiction, set against \"the reconciliation of the people of Paradise\" and the removal of rancor, and the likening of the soul to a jewel covered in dust." },
