    title: { ar: "الصبر بغير حساب: قنوت الليل وطلب العلم ومعاشرة الخلق", en: "Patience Without Reckoning: Night Devotion, Seeking Knowledge and Living with People" },
    subtitle: { ar: "خاطرة الفجر | 20 يوليو 2025", en: "Fajr Khatira | 20 July 2025" },
    excerpt: { ar: "الصبر المقصود في آية الزمر ليس قيام الليل ولا طلب العلم وحدهما، بل توطين النفس على الحال والخلق. وما دام الجزاء بغير حساب فالصبر بغير حساب.", en: "The patience meant in the verse of al-Zumar is not night prayer nor seeking knowledge alone, but settling the soul upon one's circumstance and upon people. And since the reward is without reckoning, patience is without reckoning." },
