    excerpt: { ar: "مثل الماء النازل من السماء يبيّن أن الإنسان لا يملك من الماء ولا من المال شيئًا. وفي قصة صاحب الجنتين ويونس عليه السلام تذكرة بأن الهداية بيد الله.", en: "The parable of water sent down from the sky shows that man owns nothing of water or wealth. In the story of the owner of the two gardens and of Yūnus, peace be upon him, is a reminder that guidance is in Allah's hand." },
