    subtitle: { ar: "خاطرة الفجر: ليس كل داعٍ مجابًا وليس كل شاكٍ مصابًا", en: "Fajr Khatira: Not Every Supplicant Is Answered, and Not Everyone Who Complains Is Afflicted" },
    excerpt: { ar: "ليس كل داعٍ مجابًا، فالأمر مرتبط بيقين الداعي ونفسه، وقد يُؤخَّر الجواب لمزيد ابتلاء يحبه الله من عبده. وليس كل شاكٍ مصابًا، فمن الآلام ما هو متوهَّم، وشفاؤه بالدعاء.", en: "Not every caller is answered; it depends on the caller's certainty and soul, and the answer may be delayed for further trial that Allah loves for His servant. And not every complainant is truly afflicted, for some pains are imagined, and their cure is supplication." },
