    subtitle: { ar: "خاطرة الفجر في يوم التروية", en: "A Fajr khatira on the Day of Tarwiyah" },
    excerpt: { ar: "التكبير غرسٌ لتعظيم الله في النفس، يلبّي حاجة المحتاج ويكسر استغناء المستغني، ثم أحكامه من مطلقٍ ومقيَّد، ووصية باغتنام ليلة عرفة بالطاعة والتكبير تشبّهًا بالحجيج.", en: "Takbīr plants the magnification of Allah in the soul; it meets the need of the needy and breaks the self-sufficiency of the self-sufficient. Then its rulings, absolute and restricted, and a counsel to seize the Night of ʿArafah with obedience and takbīr, in emulation of the pilgrims." },
