    excerpt: { ar: "لماذا فرض الله خمس صلوات في اليوم؟ هي فحصٌ للقلب، واختبارٌ: هل نخرج من الصلاة أشخاصًا مختلفين؟ ثم معاني «الحمد لله»: الرضا والشكر والثناء والشعور بعناية الله.", en: "Why Allah set five daily prayers: a scan for the heart, a test of whether we leave prayer a different person, and the meanings of \"Alhamdulillah\" (satisfaction, thanks, praise, being cared for)." },
