    excerpt: { ar: "عن التطوع زيادةً على الفرض: حديث «استقيموا ولن تحصوا»، وفوائد النافلة (اختبار ظن الله، وتعويض النقص، وإتقان الفرض، وملء الفراغ)، وصلاة النافلة في البيت، وفضل طول القيام.", en: "On voluntary worship beyond the obligatory: the hadith «استقيموا ولن تحصوا» (\"Be steadfast, though you will not be able to count\"), and the benefits of the supererogatory prayer (testing one's assumption about Allah, making up for shortfalls, perfecting the obligatory, filling free time), praying the voluntary prayer at home, and the merit of lengthy standing." },
