    subtitle: { ar: "معالم من سورة العنكبوت: الابتلاء، وسؤال الكدح، والصبر على الوالدين", en: "Landmarks from Sūrat al-ʿAnkabūt: Trial, the Question of Toil, and Patience with Parents" },
    excerpt: { ar: "معالم من سورة العنكبوت: الابتلاء سنة في الحياة لا يُترك الناس منه، وسؤال عن حكم المنتحر يُردّ إلى علم الله والمتخصصين.\nثم الصبر على الوالدين من أشق الابتلاءات، والآية بين آيتين تعدان بتكفير السيئات وأحسن الجزاء.", en: "Landmarks from Surat al-ʿAnkabūt: trial is a law of life from which people are not left alone, and a question about the ruling on one who commits suicide is referred to Allah's knowledge and to specialists.\nThen patience with parents as among the hardest trials, the verse set between two verses promising expiation of sins and the best reward." },
