    excerpt: { ar: "من هدايات سورة الفاتحة: الحمد والربوبية، والفرق بين الرحمن والرحيم، وأثر استحضار الاسمين في الطمأنينة، ثم مالك يوم الدين والاستعانة في الهداية.\nوتنتهي الخاطرة بدعاء المتحدث.", en: "From the guidance of Surat al-Fātiḥah: praise and lordship, the difference between al-Raḥmān and al-Raḥīm, the effect of keeping both names in mind on tranquility, then Master of the Day of Judgment and seeking help in guidance.\nThe reflection ends with the speaker's supplication." },
