    subtitle: { ar: "خاطرة ليلة القدر، 27 رمضان 1442هـ — لماذا أخفى الله موعدها، وما الذي ينزل فيها على القلوب", en: "Khatira on Laylat al-Qadr, 27 Ramadan 1442 AH — Why Allah Concealed Its Date, and What Descends Upon Hearts in It" },
    excerpt: { ar: "لماذا أخفى الله موعد ليلة القدر؟ تأمل في غاية العبادة وهي التطوّر والتزكية، وفي سورة القدر وتنزّل الملائكة والروح وسلامها.\nوالقلب وعاءٌ يلزم تطهيره ليستقبل عطاء الله في هذه الليلة.", en: "Why did Allah conceal the date of Laylat al-Qadr? A reflection on the purpose of worship, which is growth and purification, and on Surat al-Qadr, the descent of the angels and the Spirit, and its peace.\nThe heart is a vessel that must be purified to receive Allah's giving on this night." },
