    excerpt: { ar: "التكبير شعار المؤمنين من بدر إلى المساجد والأذان والصلاة، وفي ظلاله حياة عزيزة وقوة نفسية وتربية للأولاد.\nيجري التكبير في الأبدان مجرى الدم، والمطلوب أن نستعين بالله مكبّرين له فوق كل شيء.", en: "Takbīr is the slogan of the believers, from Badr to the mosques, the call to prayer, and the prayer; in its shade lie a dignified life, psychological strength, and the upbringing of children.\nTakbīr runs in bodies as blood does, and what is required is that we seek Allah's help while magnifying Him above everything." },
