    subtitle: { ar: "الخير بابٌ مفتوح لا يضيق بالصدقة وحدها: فاستبقوه، وصحِّحوا النية، وأحسنوا الأداء", en: "Goodness Is an Open Door That Charity Alone Does Not Narrow: So Race to It, Correct Your Intention, and Perfect Your Performance" },
