    subtitle: { ar: "لا تستثقل الناس: الخلق أصناف يُنبتها الله ويقطفها الموت، وفي كلٍّ منهم رسالة", en: "Do not find people burdensome: creatures of every kind, whom Allah makes grow and death plucks, and in each one a message" },
    excerpt: { ar: "لا تستثقل الناس؛ فالخلق أصناف زائلة يُنبتها الله ويقطفها الموت، وكلٌّ يعلّمك خُلقًا، ومكانتك الحقيقية عند ربك.", en: "Do not find people burdensome; creatures are transient kinds that Allah causes to grow and death plucks, each teaches you a character trait, and your true standing is with your Lord." },
