    subtitle: { ar: "من لقاء الأربعاء في الأخلاق: الحق الأول للقرآن علينا أن نعترف بوجوده", en: "From the Wednesday gathering on character: the first right of the Qur'an over us is that we acknowledge its existence" },
    excerpt: { ar: "من لقاء الأربعاء في الأخلاق: الحق الأول للقرآن علينا أن نعترف بوجوده اعترافًا يجعله مرجعًا ومنهج هداية لا مادة لفظية تمر على اللسان.\nويمضي إلى واجب الحفاظ وغير الحفاظ في حفظ القرآن وتعلّم معانيه.", en: "From the Wednesday gathering on ethics: the Qur'an's first right over us is that we acknowledge its existence in a way that makes it a reference and a method of guidance, not a verbal matter that passes over the tongue.\nHe goes on to the duty of memorizers and non-memorizers in memorizing the Qur'an and learning its meanings." },
