    excerpt: { ar: "وقفات مع سورة الأعلى بعد سورة الطارق: من عظمة الكون إلى مهمة المؤمن في التسبيح والتذكير. وتنبيه إلى تزكية النفس قبل الحكم على الناس.", en: "Pauses with Surat al-Aʿlā after Surat al-Ṭāriq: from the greatness of the cosmos to the believer's mission of glorification and reminding. And a note on purifying the self before judging people." },
