    subtitle: { ar: "التوبة مقدمةً بين يدي الحج، يشارك فيها من لم يُكتب له الحج", en: "Repentance as a prelude to Ḥajj, in which even those who were not written to perform Ḥajj can take part" },
    excerpt: { ar: "التوبة أول ما يُطلب من الحاج قبل رحلته، ويشاركه فيها من حبسه العذر. ثم الانتقال من توبة الفرد إلى توبة الأسرة والمجتمع.", en: "Repentance is the first thing asked of the pilgrim before his journey, and one kept back by an excuse shares it with him. Then the movement from individual repentance to the repentance of the family and society." },
