    excerpt: { ar: "وقفات تربوية ودعوية مع سورة المسد: الجزاء من جنس العمل، وسقوط المال أمام قضاء الله، وسنة التدافع، وأثر الزوجة في الاستقامة.\nتأتي بعد السور الثلاث الأخيرة وما فيها من تنزيه الله والاستعاذة به.", en: "Educational and da'wah pauses with Surat al-Masad: recompense matches the deed, wealth falls before Allah's decree, the law of mutual repulsion (sunnat al-tadāfuʿ), and the wife's influence on uprightness.\nIt comes after the last three surahs, with their declaration of Allah's transcendence and seeking refuge in Him." },
