    excerpt: { ar: "وقفة مع قوله تعالى «وإذ ابتلى إبراهيم ربه بكلمات»: الابتلاء سنة الحياة، والإمامة تُنال بإتمام التكليف، وحرص إبراهيم على ذريته وبيته وأمنه.\nثم تدبّر لدعواته وختام القصة: التقبّل والإتقان، والأجيال، والشقاق والهداية، والعودة إلى ملة إبراهيم.", en: "A pause at the saying of the Exalted «وإذ ابتلى إبراهيم ربه بكلمات» (\"And when his Lord tried Ibrāhīm with words\"): trial is a law of life, leadership (imāmah) is attained by completing the charge, and Ibrāhīm's concern for his offspring, his house, and its security.\nThen reflection on his supplications and the close of the story: acceptance and perfection, generations, discord and guidance, and return to the creed of Ibrāhīm." },
